/**
 * Overload resolution on top of frida-java-bridge dispatchers.
 *
 * A bridge method wrapper carries an `overloads` array where every entry
 * describes its parameter types through `argumentTypes`.  The built-in
 * `dispatcher.overload(...)` performs a linear scan with signature-string
 * construction on every call; this module resolves once and lets the kit
 * cache the concrete method wrapper.
 */

export class OverloadError extends Error {
  constructor (message, available) {
    super(message);
    this.name = 'OverloadError';
    this.available = available;
  }
}

function describeSignature (method) {
  return method.argumentTypes.map(t => t.className);
}

function formatAvailable (methodName, overloads) {
  return overloads.map(m => {
    const params = describeSignature(m);
    return params.length === 0
      ? '\t.' + methodName + '.overload()'
      : '\t.' + methodName + '.overload(\'' + params.join('\', \'') + '\')';
  }).join('\n');
}

function equalSignature (method, wanted) {
  const { argumentTypes } = method;
  if (argumentTypes.length !== wanted.length) {
    return false;
  }
  for (let i = 0; i !== wanted.length; i++) {
    if (argumentTypes[i].className !== wanted[i]) {
      return false;
    }
  }
  return true;
}

/**
 * Resolve one concrete method wrapper.
 *
 * @param {object} dispatcher bridge method wrapper obtained from `Class[name]`
 * @param {string[]|undefined} argTypes explicit JNI type names, or undefined
 *   when the caller wants the unique overload (and accepts an error if the
 *   name is ambiguous).
 */
export function resolveOverload (dispatcher, argTypes) {
  const { overloads } = dispatcher;
  const methodName = dispatcher.methodName;

  if (overloads.length === 1 && argTypes === undefined) {
    return overloads[0];
  }

  if (argTypes === undefined) {
    throw new OverloadError(
      methodName + '(): ambiguous overload, specify an argument signature:\n' +
        formatAvailable(methodName, overloads),
      overloads.map(describeSignature)
    );
  }

  for (const method of overloads) {
    if (equalSignature(method, argTypes)) {
      return method;
    }
  }

  throw new OverloadError(
    methodName + '(): no overload matches (' + argTypes.join(', ') + '):\n' +
      formatAvailable(methodName, overloads),
    overloads.map(describeSignature)
  );
}

/**
 * Resolve every overload (or every overload matching a filter).  Used by the
 * batch hooker when a spec wants one handler attached to all variants of a
 * method name.
 *
 * @param {object} dispatcher bridge method wrapper
 * @param {Function} [predicate] optional filter receiving a concrete method
 */
export function resolveAllOverloads (dispatcher, predicate) {
  if (predicate === undefined) {
    return dispatcher.overloads.slice();
  }
  return dispatcher.overloads.filter(predicate);
}

/**
 * Signature string used both as a cache key and for user-facing diagnostics.
 */
export function signatureOf (method) {
  return describeSignature(method).join(',');
}

/**
 * Helpers for hook callbacks.
 *
 * The single biggest per-invocation cost in hand-written Frida Java hooks is
 * traffic across the JS <-> native bridge:
 *
 *   - `this.method.apply(this, args)` re-enters the dispatcher, which walks
 *     every overload and re-checks argument compatibility before calling.
 *   - Looking up `Java.use(...)` inside the callback repeats class resolution
 *     on every invocation.
 *   - Eagerly materializing every JNI argument (the bridge already converts
 *     arguments for the JS handler, but user code often re-wraps them or
 *     builds throwaway arrays) adds more marshalling.
 *
 * The kit resolves the concrete original method wrapper once at install time
 * and hands the callback a bound `callOriginal` that invokes that exact
 * overload directly, skipping the dispatcher scan entirely.
 */

/**
 * Bind an already-resolved concrete overload to a receiver.
 *
 * @param {object} method a concrete method wrapper from `resolveOverload`
 * @param {object} receiver the `this` of the hooked instance method, or the
 *   class wrapper for a static method
 * @returns {Function} `(...args) => retval` targeting the original code
 */
export function bindOriginal (method, receiver) {
  return function callOriginal (...args) {
    return method.apply(receiver, args);
  };
}

/**
 * Wrap a user handler so it receives a normalized invocation context instead
 * of raw argument lists.  The wrapper itself does zero bridge work beyond the
 * argument conversion frida-java-bridge already performs; every helper it
 * exposes is a plain JS closure over cached references.
 *
 * @param {object} method concrete overload being hooked
 * @param {Function} handler user callback `(args, ctx) => retval`
 * @param {object} extras additional cached resources exposed on the context
 */
export function makeInvocationHandler (method, handler, extras = {}) {
  const isStatic = method.type === 2; // ClassFactory STATIC_METHOD

  return function invocationHandler (...args) {
    const receiver = isStatic ? method.holder : this;
    const ctx = {
      method,
      methodName: method.methodName,
      className: method.holder.$n,
      static: isStatic,
      callOriginal: bindOriginal(method, receiver),
      ...extras
    };
    return handler(args, ctx);
  };
}

/**
 * Pass-through handler: forwards every call untouched.  Useful for benchmark
 * baselines and for temporarily neutralizing a hook without reverting the
 * ART method patch.
 */
export function passthroughHandler (method) {
  return makeInvocationHandler(method, (args, ctx) => ctx.callOriginal(...args));
}

