    return makeInvocationHandler(method, (args, ctx) => {
      if (typeof onEnter === 'function') {
        onEnter(args, ctx);
      }
      const retval = ctx.callOriginal(...args);
      if (typeof onLeave === 'function') {
        return onLeave(retval, args, ctx);
      }
      return retval;
    }, spec.extras);
