   * Revert one concrete overload to its previous implementation.
   */
  revert (key) {
    const record = this.installed.get(key);
    if (record === undefined) {
      return false;
    }
    record.method.implementation = record.originalImpl;
    this.installed.delete(key);
    return true;
  }

