  const start = process.hrtime.bigint();
  let sink = 0;
  for (let i = 0; i < iterations; i++) {
    sink = callback(i);
  }
  const elapsedNs = Number(process.hrtime.bigint() - start);

  return {
    label,
    iterations,
    elapsedMs: elapsedNs / 1e6,
    nsPerOp: elapsedNs / iterations,
    sink
  };
